SELECT  coalesce(json_agg("root" ORDER BY "root.pg.author_id" DESC NULLS FIRST, "root.pg.id" ASC NULLS LAST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id", "_root.base"."author_id" AS "author_id", "_root.ar.root.revisions"."revisions" AS "revisions", "_root.ar.root.comments"."comments" AS "comments", "_root.ar.root.latest"."latest" AS "latest"       ) AS "_e"      ) ) AS "root", "_root.base"."author_id" AS "root.pg.author_id", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."article"  WHERE ('true')   ORDER BY "author_id" DESC NULLS FIRST, "id" ASC NULLS LAST  ) AS "_root.base" LEFT OUTER JOIN LATERAL (SELECT  coalesce(json_agg("latest" ORDER BY "root.ar.root.latest.pg.note" DESC NULLS FIRST), '[]' ) AS "latest" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.latest.base"."note" AS "note", "_root.ar.root.latest.or.article"."article" AS "article"       ) AS "_e"      ) ) AS "latest", "_root.ar.root.latest.base"."note" AS "root.ar.root.latest.pg.note" FROM  (SELECT  *  FROM "public"."revision"  WHERE ((("_root.base"."id") = ("article_id")) AND (("_root.base"."author_id") = ("author_id")))   ORDER BY "note" DESC NULLS FIRST LIMIT 1 ) AS "_root.ar.root.latest.base" LEFT OUTER JOIN LATERAL (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.latest.or.article.base"."title" AS "title"       ) AS "_e"      ) ) AS "article" FROM  (SELECT  *  FROM "public"."article"  WHERE ((("_root.ar.root.latest.base"."author_id") = ("author_id")) AND (("_root.ar.root.latest.base"."article_id") = ("id")))    LIMIT 1 ) AS "_root.ar.root.latest.or.article.base"      ) AS "_root.ar.root.latest.or.article" ON ('true')    ORDER BY "root.ar.root.latest.pg.note" DESC NULLS FIRST  ) AS "_root.ar.root.latest"      ) AS "_root.ar.root.latest" ON ('true') LEFT OUTER JOIN LATERAL (SELECT  coalesce(json_agg("comments" ), '[]' ) AS "comments" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.comments.base"."id" AS "id"       ) AS "_e"      ) ) AS "comments" FROM  (SELECT  *  FROM "public"."comment"  WHERE (("_root.base"."id") = ("article_id"))     ) AS "_root.ar.root.comments.base"      ) AS "_root.ar.root.comments"      ) AS "_root.ar.root.comments" ON ('true') LEFT OUTER JOIN LATERAL (SELECT  coalesce(json_agg("revisions" ), '[]' ) AS "revisions" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.revisions.base"."note" AS "note"       ) AS "_e"      ) ) AS "revisions" FROM  (SELECT  *  FROM "public"."revision"  WHERE ((("_root.base"."id") = ("article_id")) AND (("_root.base"."author_id") = ("author_id")))     ) AS "_root.ar.root.revisions.base"      ) AS "_root.ar.root.revisions"      ) AS "_root.ar.root.revisions" ON ('true')    ORDER BY "root.pg.author_id" DESC NULLS FIRST, "root.pg.id" ASC NULLS LAST  ) AS "_root"      
